#include "emit.hpp"

#include <format>

namespace gen {
namespace {

std::string preamble(const Output& o, std::string_view what) {
  return std::format(
      "// {} -- generated by orchestra_gen from {} ({}). Do not edit.\n"
      "// Source data: FIX Orchestra, (c) FIX Protocol Limited, Apache License 2.0; only names, tag numbers,\n"
      "// code values and structure are copied, no documentation text.\n",
      what, o.source, o.version);
}

std::string char_lit(const std::string& v) {
  const char c = v[0];
  if (c == '\'') return "'\\''";
  if (c == '\\') return "'\\\\'";
  return std::string("'") + c + "'";
}

void emit_part(std::string& s, const Part& p, target t) {
  s += std::format("struct {} {{\n", p.name);
  for (const auto& m : p.layout) {
    const auto bits = m.type.bits ? std::format(" : {}", m.type.bits) : std::string{};
    if (t == target::clang23) s += std::format("  GLZ_FIX3_TAG({}) {} {}{};\n", m.tag, m.type.cpp, m.name, bits);
    else s += std::format("  [[=glz::fix3::tag{{{}}}]] {} {}{};\n", m.tag, m.type.cpp, m.name, bits);
  }
  s += "\n";
  if (!p.msg_type.empty()) s += std::format("  static constexpr std::string_view fix_msg_type = \"{}\";\n", p.msg_type);
  s += std::format("  static constexpr std::string_view fix_name = \"{}\";\n", p.fix_name);
  s += std::format("  // Codec contract (CONTRACT.md): the tag table in dictionary (wire) order. member = the member's\n"
                   "  // position in declaration (layout) order, the same index fix_visit passes and reflection sees.\n"
                   "  //   {{tag, member, name, fix_name, required, group, length_tag, max_entries, deprecated, open_enum, datatype}}\n"
                   "  static constexpr std::array<glz::fix3::field_info, {}> fix_fields{{{{\n",
                   p.wire_order.size());
  for (std::size_t i = 0; i < p.wire_order.size(); ++i) {
    const auto& m = p.wire_order[i];
    s += std::format("      {{{}, {}, \"{}\", \"{}\", {}, {}, {}, {}, {}, {}, \"{}\"}},\n", m.tag, p.member_index[i], m.name, m.fix_name,
                     m.required, m.kind == member_kind::group, m.length_tag, m.max_entries, m.deprecated, m.open_enum, m.datatype);
  }
  s += "  }};\n\n";
  // Reflection-free access (works on every compiler, LLVM 23 included): f(field_info, member) in wire order.
  // A bit-field has no address, so it is passed as a glz::fix3::bit_ref proxy with get() and set().
  s += "  // f(info, member) for every field and group in wire order; no reflection needed. Bit-fields come as\n"
       "  // glz::fix3::bit_ref (get/set; a const message gets read_only, so set() does not compile).\n"
       "  // Unknown tags are not in the part: they are kept on the envelope, glz::fix3::message::unknown.\n"
       "  template <class Self, class F> constexpr void fix_visit(this Self&& self, F&& f) {\n";
  for (std::size_t i = 0; i < p.wire_order.size(); ++i) {
    const auto& m = p.wire_order[i];
    if (m.type.bits)
      s += std::format("    if constexpr (std::is_const_v<std::remove_reference_t<Self>>)\n"
                       "      f(fix_fields[{0}], glz::fix3::bit_ref{{[&] {{ return bool(self.{1}); }}, glz::fix3::read_only{{}}}});\n"
                       "    else\n"
                       "      f(fix_fields[{0}], glz::fix3::bit_ref{{[&] {{ return bool(self.{1}); }}, [&](bool v) {{ self.{1} = v; }}}});\n",
                       i, m.name);
    else
      s += std::format("    f(fix_fields[{}], self.{});\n", i, m.name);
  }
  s += "  }\n};\n";
  s += std::format("static_assert(sizeof({0}) == {1} && alignof({0}) == {2});\n", p.name, p.size, p.align);
  s += "\n";
}

}  // namespace

std::string emit_enums(const Output& o) {
  std::string s = preamble(o, o.ns + "_enums.hpp");
  s += "#pragma once\n#include <cstdint>\n\n";
  s += std::format("namespace {} {{\n\n", o.ns);
  s += "// A char codeSet is enum class X : char whose values are the wire characters (whole byte). An int\n"
       "// codeSet uses the smallest integer type that holds every legal value and leaves max() free for\n"
       "// \"absent\"; a field marked unionDataType Reserved<N>Plus allows values beyond the codes, so 32 bits.\n";
  for (const auto& e : o.enums) {
    s += std::format("enum class {} : {} {{", e.name, e.underlying);
    bool first = true;
    for (const auto& v : e.values) {
      s += std::format("{}\n  {} = {}", first ? "" : ",", v.name, e.kind == enum_kind::char_ ? char_lit(v.value) : v.value);
      first = false;
    }
    s += "\n};\n";
  }
  s += std::format("\n}}  // namespace {}\n", o.ns);
  return s;
}

std::optional<target> parse_target(std::string_view s) {
  if (s == "gcc16") return target::gcc16;
  if (s == "p2996") return target::p2996;
  if (s == "clang23") return target::clang23;
  return std::nullopt;
}

std::string_view target_name(target t) {
  switch (t) {
    case target::gcc16: return "gcc16";
    case target::p2996: return "p2996";
    case target::clang23: return "clang23";
  }
  return "?";
}

std::string emit_structs(const Output& o, target t) {
  std::string s = preamble(o, o.ns + ".hpp");
  s += std::format("// Generated for --target {}.\n#pragma once\n", target_name(t));
  // Refuse a compiler this header was not generated for, instead of silently losing the tag annotations.
  const auto hdr = o.ns + ".hpp";
  switch (t) {
    case target::gcc16:
      s += std::format("#if defined(__clang__) || !defined(__cpp_impl_reflection)\n"
                       "#error \"{} was generated for GCC 16 (--target gcc16): build with g++-16 -std=c++26 -freflection, "
                       "or regenerate with --target p2996 / clang23\"\n#endif\n", hdr);
      break;
    case target::p2996:
      s += std::format("#if !defined(__clang__) || !defined(__has_feature)\n"
                       "#error \"{0} was generated for clang-p2996 (--target p2996): regenerate with --target gcc16 or clang23\"\n"
                       "#elif !__has_feature(annotation_attributes)\n"
                       "#error \"{0} needs C++26 annotations: build clang-p2996 with -freflection -fannotation-attributes, "
                       "or regenerate with --target clang23\"\n#endif\n", hdr);
      break;
    case target::clang23:
      s += std::format("#if defined(__cpp_impl_reflection)\n"
                       "#error \"{0} was generated for a compiler without annotations (--target clang23); regenerate with --target gcc16\"\n"
                       "#elif defined(__has_feature)\n#if __has_feature(annotation_attributes)\n"
                       "#error \"{0} was generated for a compiler without annotations (--target clang23); regenerate with --target p2996\"\n"
                       "#endif\n#endif\n"
                       "// No C++26 annotations on this compiler: GLZ_FIX3_TAG(N) expands to nothing, and tags come from fix_fields.\n", hdr);
      break;
  }
  s += std::format("#include \"glaze_fix3_support.hpp\"\n#include \"{}_enums.hpp\"\n\n", o.ns);
  s += std::format("namespace {} {{\n\nnamespace dec = boost::decimal;\n\n", o.ns);
  s += "// ---- per-version constants ----\n";
  s += std::format("inline constexpr std::string_view dictionary_version = \"{}\";  // {}\n", o.dictionary, o.version);
  s += std::format("inline constexpr std::string_view begin_string = \"{}\";  // tag 8 on the wire\n", o.begin_string);
  if (!o.appl_ver_id.empty())
    s += std::format("inline constexpr std::string_view appl_ver_id = \"{}\";  // tag 1128\n", o.appl_ver_id);
  s += std::format("// (length tag, data tag): the data field's bytes may contain SOH; its length comes first\n"
                   "inline constexpr std::array<std::array<std::uint16_t, 2>, {}> length_data_pairs{{{{\n", o.length_data.size());
  for (const auto& [l, d] : o.length_data) s += std::format("    {{{}, {}}},\n", l, d);
  s += "}};\n\nnamespace tag {\n";
  for (const auto& [id, n] : o.tags) s += std::format("inline constexpr std::uint16_t {} = {};\n", n, id);
  s += "}  // namespace tag\n\n";
  s += "// ---- repeating-group entries ----\n";
  for (const auto& p : o.entries) emit_part(s, p, t);
  s += "// ---- header and trailer ----\n";
  emit_part(s, o.header, t);
  emit_part(s, o.trailer, t);
  s += "// ---- messages ----\n";
  for (const auto& p : o.messages) {
    emit_part(s, p, t);
    s += std::format("template <glz::fix3::unknown_policy U>\nusing {0}_message = glz::fix3::message<{1}, {0}, {2}, U>;\n\n",
                     p.name, o.header.name, o.trailer.name);
  }
  s += std::format("}}  // namespace {}\n", o.ns);
  return s;
}

std::string emit_digest(const Output& o) {
  // One line per record; parsed at compile time by glz::fix3::embed::define_all.
  //   P <name> <size> <align>
  //   M <name> <type> <tag> <bits>
  std::string s = std::format("V 2 {}\n", o.ns);
  const auto part = [&](const Part& p) {
    s += std::format("P {} {} {}\n", p.name, p.size, p.align);
    for (const auto& m : p.layout)
      s += std::format("M {} {} {} {}\n", m.name, m.type.digest, m.tag, m.type.bits);
  };
  for (const auto& p : o.entries) part(p);
  part(o.header);
  part(o.trailer);
  for (const auto& p : o.messages) part(p);
  return s;
}

std::string emit_module(const Output& o) {
  std::string s = preamble(o, o.ns + "_embed.cppm");
  s += "// The C++26 path: the same structs as " + o.ns + ".hpp, built at compile time by define_aggregate from\n"
       "// the #embed'ed digest. GCC 16.2 and clang-p2996 only (upstream Clang has no reflection yet).\n"
       "// C++26 cannot name a new class from a string, so the declarations below are written out.\n";
  s += std::format("module;\n#include \"glaze_fix3_embed.hpp\"\n#include \"{}_enums.hpp\"\nexport module {}_embed;\n\n", o.ns, o.ns);
  s += std::format("export namespace {}_embed {{\n", o.ns);
  const auto decl = [&](const Part& p) {
    s += std::format("struct {};\n", p.name);
  };
  for (const auto& p : o.entries) decl(p);
  decl(o.header);
  decl(o.trailer);
  for (const auto& p : o.messages) decl(p);
  s += std::format("}}  // namespace {}_embed\n\n", o.ns);
  s += std::format("namespace {}_embed_detail {{\nconstexpr unsigned char digest[] = {{\n#embed \"{}.digest\"\n}};\n}}\n\n", o.ns, o.ns);
  s += std::format("consteval {{ glz::fix3::embed::define_all(^^{0}_embed, ^^{0}, {0}_embed_detail::digest); }}\n", o.ns);
  return s;
}

}  // namespace gen
